<script>
import CategoryManager from './CategoryManager.svelte';import {visibleChannels,lastOpenedChannel} from './playlist-preferences.js';import TVCatalog from './TVCatalog.svelte';import {moveFocus,focusControl} from './tv-navigation.js';import {refreshAtStartup} from './startup-refresh.js';import {readTextStream,parsePlaylist,parsePlaylistStream,formatBytes,byteProgress,yieldUI} from './playlist-import.js';import Logo from './Logo.svelte';import Player from './Player.svelte';import Intro from './Intro.svelte';import Catalog from './Catalog.svelte';import {separator,kind,indexCatalogue,filterCatalogue,currentGuide} from './catalog.js';import Hls from 'hls.js';import {isAndroid,isDesktop,isNative,NativePlayer,nativeText,nativePlaylist,nativeDeviceInfo,playbackState,resumePlayback,stopPlayback,exitToHome,watchPlayback} from './native.js';import {playlistResponse,browserNetworkError} from './playlist-network.js';import {get,set,update} from 'idb-keyval';import {tick,onDestroy,onMount} from 'svelte';
let lists=$state.raw([]),active=$state(''),page=$state('playlists'),query=$state(''),group=$state('Tutti'),favorites=$state([]),name=$state(''),url=$state(''),epgUrl=$state(''),message=$state(''),epgMessage=$state(''),playbackMode=$state('auto'),busy=$state(false),selected=$state(null),video=$state(),hls,programs=$state.raw([]),clock=$state(Date.now());
let loading=$state(null),failedSource=$state(''),tvMode=true,currentPlayback=$state(null),startupRefreshing=$state(false),refreshLabel=$state(''),searchQuery=$state('');
let categoryEditor=$state(null),lastOpened=$state.raw({});
let playbackPoll,playbackSubscription,destroyed=false;
$effect(()=>{const value=query;const timeout=setTimeout(()=>searchQuery=value,180);return()=>clearTimeout(timeout);});
let visibleCount=$state(100),intro=$state(true),catalogMode=$state('live'),view=$state('catalog'),playbackError=$state('');let playbackTimer;
$effect(()=>{catalogMode;visibleCount=100;});
$effect(()=>{query;group;active;visibleCount=100;});
let storageReady=$state(false);
onMount(()=>{void boot();window.addEventListener('tuca-back',back);return()=>{destroyed=true;window.removeEventListener('tuca-back',back);clearInterval(playbackPoll);playbackSubscription?.remove();};});
async function boot(){
 try{let saved=await get('tucatv');if(!saved){saved=JSON.parse(localStorage.getItem('tucatv')||'{}');await set('tucatv',saved);localStorage.removeItem('tucatv');}lists=(saved.lists||[]).map(p=>({...p,epg:p.epg===p.source?'':p.epg}));favorites=saved.favorites||[];active=lists[0]?.id||'';if(lists.length)page='channels';}catch{message='Impossibile leggere i dati locali.';}
 try{lastOpened=await get('tuca-last-opened')||{};}catch{}
 storageReady=true;await tick();ensureFocus();
 if(isAndroid){try{playbackSubscription=await watchPlayback(state=>{currentPlayback=state.available?state:null;ensureFocus();});if(destroyed){await playbackSubscription.remove();return;}await syncPlayback();playbackPoll=setInterval(()=>{if(!document.hidden)syncPlayback();},4000);}catch{}}
 await autoRefresh();
}
async function syncPlayback(){try{const state=await playbackState();currentPlayback=state.available?state:null;}catch{}}
async function returnToPlayer(){try{await resumePlayback();}catch{await syncPlayback();message='La riproduzione è terminata. Seleziona nuovamente un canale.';}}
async function stopCurrent(){try{await stopPlayback();currentPlayback=null;await tick();ensureFocus();}catch{message='Impossibile interrompere la riproduzione.';}}
function ensureFocus(){if(!tvMode||intro||!storageReady)return;const focused=document.activeElement;if(!focused||focused===document.body||!focused.isConnected)focusControl(document.querySelector('.tv-tile,aside button.chosen,aside button'));}
$effect(()=>{tvMode;intro;storageReady;page;tick().then(ensureFocus);});
async function autoRefresh(){
 if(busy||!lists.some(p=>p.source)||destroyed)return;busy=true;startupRefreshing=true;message='';failedSource='';
 const result=await refreshAtStartup(lists,active,async(p,position)=>{refreshLabel=p.name+' · '+position.index+'/'+position.total;await refreshOne(p);});
 startupRefreshing=false;busy=false;refreshLabel='';loading={phase:result.failed?'error':'done',title:result.failed?'Aggiornamento parziale':'Playlist aggiornate',detail:result.updated+' aggiornate'+(result.failed?' · '+result.failed+' non raggiungibili: uso la copia salvata.':'. La raccolta è pronta.'),percent:result.failed?null:100};await tick();ensureFocus();
}
const timer=setInterval(()=>clock=Date.now(),30000);onDestroy(()=>{clearInterval(timer);stop();});
let playlist=$derived(lists.find(p=>p.id===active)),channels=$derived(visibleChannels(playlist?.channels||[],playlist?.hiddenGroups||[])),catalogIndex=$derived(indexCatalogue(channels)),groups=$derived(['Tutti','Preferiti',...catalogIndex[catalogMode+'Groups']]),filtered=$derived(filterCatalogue(catalogIndex[catalogMode],searchQuery,group,favorites)),guideIndex=$derived(currentGuide(programs,clock)),lastChannel=$derived(lastOpenedChannel(channels,lastOpened[active]));
async function save(){try{await set('tucatv',{lists,favorites:$state.snapshot(favorites)});}catch{message='Impossibile salvare: controlla lo spazio disponibile sul dispositivo.';}}
function safe(s,base){if(typeof s!=='string'||!s.trim())return '';try{let u=new URL(s,base);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}}
async function fetchText(u,onProgress){if(!safe(u))throw Error('Inserisci un URL HTTP o HTTPS valido.');if(isNative)return nativeText(u,onProgress);const r=await playlistResponse(u);const total=r.headers.get('content-encoding')?0:Number(r.headers.get('content-length'))||0;try{if(r.body)return await readTextStream(r.body,{total,onProgress});return await r.text();}catch(error){throw browserNetworkError(error);}}
async function importPlaylist(source,file){
 if(file)return parsePlaylistStream(file.stream(),undefined,{total:file.size,onProgress:parseProgress});
 if(!safe(source))throw Error('Inserisci un URL HTTP o HTTPS valido.');
 if(isAndroid){const download=await nativePlaylist(source,downloadProgress);try{return await parsePlaylistStream(download.stream,source,{total:download.total,onProgress:parseProgress});}finally{await download.dispose();}}
 if(isDesktop)return parsePlaylist(await nativeText(source,downloadProgress),source,parseProgress);
 try{const response=await playlistResponse(source);const total=response.headers.get('content-encoding')?0:Number(response.headers.get('content-length'))||0;
  if(!response.body)throw Error('Questo browser non supporta l’importazione a blocchi. Salva il file M3U e usa «Carica file».');
  return await parsePlaylistStream(response.body,source,{total,onProgress:p=>{loading={phase:'download',title:'Download e lettura della playlist',detail:formatBytes(p.received)+(p.total?' di '+formatBytes(p.total):' ricevuti')+' · '+p.count.toLocaleString('it')+' canali trovati',percent:p.percent};}});
 }catch(error){if(!startupRefreshing)failedSource=source;throw browserNetworkError(error);}
}
function downloadProgress(p){loading={phase:'download',title:'Download della playlist',detail:formatBytes(p.received)+(p.total?' di '+formatBytes(p.total):' ricevuti · dimensione totale non disponibile'),percent:p.percent};}
function parseProgress(p){loading={phase:'parse',title:'Lettura dei canali',detail:p.count.toLocaleString('it')+' canali trovati',percent:p.percent};}
async function persistImport(nextLists){loading={phase:'save',title:'Salvataggio sul dispositivo',detail:'La playlist sarà pronta al termine del salvataggio.',percent:null};await tick();await yieldUI();try{await set('tucatv',{lists:nextLists,favorites:$state.snapshot(favorites)});}catch{throw Error('Impossibile salvare: controlla lo spazio disponibile sul dispositivo.');}lists=nextLists;}
async function add(file){if(busy)return;busy=true;message='';failedSource='';const source=url,label=name.trim()||file?.name||'La mia playlist',guide=epgUrl;loading={phase:'download',title:file?'Lettura del file':'Connessione alla sorgente',detail:file?file.name:'In attesa della risposta del server…',percent:null};await tick();await yieldUI();try{const parsed=await importPlaylist(source,file);const p={id:Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join(''),name:label,source:file?'':source,...parsed,epg:safe(guide)||parsed.epg,updated:Date.now()};await persistImport([...lists,p]);active=p.id;name='';url='';epgUrl='';page='channels';loading={phase:'done',title:'Playlist pronta',detail:parsed.channels.length.toLocaleString('it')+' canali caricati e salvati',percent:100};loadEpg();}catch(e){message=e.message;loading={phase:'error',title:'Caricamento non completato',detail:'Controlla il messaggio di errore e riprova.',percent:null};}finally{busy=false;}}
async function refreshOne(p){loading={phase:'download',title:'Aggiornamento playlist',detail:'Connessione alla sorgente…',percent:null};await tick();const parsed=await importPlaylist(p.source);await persistImport(lists.map(x=>x.id===p.id?{...x,...parsed,epg:x.epg||parsed.epg,updated:Date.now()}:x));if(active===p.id)loadEpg();}
async function refresh(p){if(busy)return;busy=true;message='';failedSource='';try{await refreshOne(p);loading={phase:'done',title:'Playlist aggiornata',detail:'La raccolta è stata aggiornata e salvata.',percent:100};}catch(e){message='Aggiornamento fallito: '+e.message;loading={phase:'error',title:'Aggiornamento non completato',detail:'La playlist precedente è stata conservata.',percent:null};}finally{busy=false;}}
function remove(id){if(busy)return;lists=lists.filter(p=>p.id!==id);if(active===id)active=lists[0]?.id||'';save();}
function favorite(c){favorites=favorites.includes(c.url)?favorites.filter(u=>u!==c.url):[...favorites,c.url];const snapshot=$state.snapshot(favorites);update('tucatv',saved=>({...saved,favorites:snapshot})).catch(()=>message='Impossibile salvare i preferiti.');}
function date(s){let m=s?.match(/^(\d{4})(\d{2})(\d{2})(\d{2})(\d{2})(\d{2})?\s*([+-]\d{4})?/);return m?Date.parse(m[1]+'-'+m[2]+'-'+m[3]+'T'+m[4]+':'+m[5]+':'+(m[6]||'00')+(m[7]?m[7].slice(0,3)+':'+m[7].slice(3):'Z')):NaN;}
let epgRequest=0;
async function loadEpg(file){const request=++epgRequest;const owner=active;epgMessage='';programs=[];if(!file&&!playlist?.epg)return;try{let doc=new DOMParser().parseFromString(file?await file.text():await fetchText(playlist.epg),'text/xml');if(request!==epgRequest||owner!==active)return;if(doc.querySelector('parsererror')||!doc.querySelector('tv'))throw Error('XML non valido');programs=[...doc.querySelectorAll('programme')].map(p=>({channel:p.getAttribute('channel'),start:date(p.getAttribute('start')),end:date(p.getAttribute('stop')),title:p.querySelector('title')?.textContent||'',description:p.querySelector('desc')?.textContent||''}));epgMessage='Guida TV caricata.';}catch{if(request===epgRequest&&owner===active)epgMessage='Guida TV non disponibile: verifica la sorgente XMLTV. Questo non impedisce la riproduzione dei canali.';}}
function now(c){return guideIndex.now.get(c?.tvg)}
function next(c){return guideIndex.next.get(c?.tvg)}
function time(t){return new Date(t).toLocaleTimeString('it',{hour:'2-digit',minute:'2-digit'})}
function stop(){clearTimeout(playbackTimer);hls?.destroy();hls=null;if(video){video.pause();video.removeAttribute('src');video.load();}}
let playRequest=0, fallbackUsed=false;
function fail(text){clearTimeout(playbackTimer);playbackError=text;hls?.destroy();hls=null;if(video){video.pause();video.removeAttribute('src');video.load();}}
function startHls(c,request){
 fallbackUsed=true;
 if(video.canPlayType('application/vnd.apple.mpegurl')){video.src=c.url;video.play().catch(()=>{});return;}
 if(!Hls.isSupported()){fail('Questo browser non supporta HLS. Apri la sorgente con un player esterno.');return;}
 hls=new Hls();hls.on(Hls.Events.ERROR,(_,d)=>{if(request!==playRequest||!d.fatal)return;const status=d.response?.code;fail(status?'La sorgente ha risposto con HTTP '+status+'. Verifica accesso e validità del link.':d.type===Hls.ErrorTypes.NETWORK_ERROR?'Il browser non riesce a leggere lo stream: possibili permessi CORS, errore di rete o accesso negato. Il browser non permette di distinguere sempre queste cause.':'Il contenuto non è HLS valido oppure usa codec non supportati dal browser.');});
 hls.on(Hls.Events.MANIFEST_PARSED,()=>{if(request===playRequest)video?.play().catch(()=>{});});hls.loadSource(c.url);hls.attachMedia(video);
}
function mediaError(){if(!video?.getAttribute('src')||page!=='player'||playbackError)return;
 if(playbackMode==='auto'&&!fallbackUsed&&!/\.(mp4|mkv|avi|mov|webm|m4v)(?:[?#]|$)/i.test(selected.url)&&Hls.isSupported()){video.removeAttribute('src');video.load();startHls(selected,playRequest);return;}
 fail(video.error?.code===2?'Download dello stream fallito. Verifica la connessione e i permessi della sorgente.':'Formato o codec non riproducibile in questo browser, oppure accesso alla sorgente negato. Il supporto di VLC è diverso da quello del browser.');
}
function exportSelected(){const blob=new Blob(['#EXTM3U\n#EXTINF:-1,'+selected.name.replace(/[\r\n]/g,' ')+'\n'+selected.url+'\n'],{type:'audio/x-mpegurl'});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='TucaTV-stream.m3u';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function rememberOpened(c){lastOpened={...lastOpened,[active]:{url:c.url,at:Date.now()}};set('tuca-last-opened',lastOpened).catch(()=>{});}
async function editCategories(p){categoryEditor=p.id;await tick();focusControl(document.querySelector('.category-manager input'));}
async function saveCategories(value){const hidden=$state.snapshot(value);const id=categoryEditor;await update('tucatv',saved=>({...saved,lists:(saved?.lists||lists).map(p=>p.id===id?{...p,hiddenGroups:hidden}:p)}));lists=lists.map(p=>p.id===id?{...p,hiddenGroups:hidden}:p);group='Tutti';}
async function play(c){
 if(separator(c)){message='Questa voce è un separatore: seleziona un canale reale.';return;}
 rememberOpened(c);
 if(isNative){message='';try{const pool=filtered.some(x=>x.url===c.url)?filtered:[c,...filtered];const index=pool.findIndex(x=>x.url===c.url);const start=Math.max(0,index-50);await NativePlayer.play({url:c.url,title:c.name,queue:pool.slice(start,index+51).map(x=>({url:x.url,title:x.name})),index:index-start});}catch{message='Impossibile aprire il player nativo.';}return;}
 const request=++playRequest;stop();selected=c;page='player';message='';playbackError='';fallbackUsed=false;await tick();if(request!==playRequest||page!=='player')return;
 if(location.protocol==='https:'&&new URL(c.url).protocol==='http:'){fail('TucaTV non ha avviato questa sorgente HTTP dalla pagina HTTPS, per evitare blocchi o aggiornamenti automatici del link da parte del browser. Usa l’app Android o VLC; per il player web richiedi al gestore una sorgente HTTPS compatibile.');return;}
 playbackTimer=setTimeout(()=>{if(request===playRequest&&video.readyState<2)fail('La sorgente non ha fornito video entro 20 secondi. Verifica il link e i permessi CORS oppure aprila in VLC.');},20000);
 const isHls=/\.m3u8(?:[?#]|$)|[?&]output=m3u8(?:&|$)/i.test(c.url);
 if(playbackMode==='hls'||(playbackMode==='auto'&&isHls))startHls(c,request);else{video.src=c.url;video.play().catch(()=>{});}
}
function nav(p){++playRequest;stop();categoryEditor=null;page=p;message='';}
function demo(){if(busy)return;let p={id:Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join(''),name:'Playlist di esempio',channels:[{name:'Big Buck Bunny',kind:'vod',group:'Demo',tvg:'',url:'https://test-streams.mux.dev/x36xhzz/x36xhzz.m3u8'},{name:'Sintel',group:'Demo',tvg:'',url:'https://storage.googleapis.com/gtv-videos-bucket/sample/Sintel.mp4'}],updated:Date.now(),source:'',epg:''};lists=[...lists,p];active=p.id;save();page='channels';catalogMode='vod';programs=[];}
function changeChannel(step){const pool=filtered;const i=pool.findIndex(c=>c.url===selected?.url);if(pool.length)play(pool[(i+step+pool.length)%pool.length]);}
function back(){if(categoryEditor){categoryEditor=null;tick().then(ensureFocus);return;}if(intro){intro=false;return;}if(page==='player'){nav('channels');return;}if(tvMode&&!document.activeElement?.closest('aside')){focusControl(document.querySelector('aside button.chosen,aside button'));return;}if(page!=='channels'&&lists.length){nav('channels');return;}if(isAndroid)exitToHome();else if(page!=='playlists')nav('playlists');}
let lastDirection=0;
function keys(e){
 if(e.defaultPrevented)return;
 if(e.key==='Escape'||e.key==='BrowserBack'){e.preventDefault();back();return;}
 if(!['ArrowDown','ArrowUp','ArrowLeft','ArrowRight'].includes(e.key))return;
 const element=document.activeElement;
 if(element?.tagName==='SELECT'||element?.tagName==='VIDEO')return;
 if(element?.tagName==='INPUT'&&(!tvMode||['ArrowLeft','ArrowRight'].includes(e.key)))return;
 e.preventDefault();if(e.repeat&&performance.now()-lastDirection<90)return;lastDirection=performance.now();moveFocus(e.key,intro?document.querySelector('.startup'):document);
}

</script>
<svelte:window onkeydown={keys}/>
{#if intro}<Intro ondone={()=>intro=false}/>{/if}
<div class="shell tv-mode tv-first" class:android-shell={isAndroid} inert={intro}>
<aside><a class="brand" href="#home" onclick={()=>nav('playlists')}><img class="brand-mark" src="/tucatv-mark.svg" alt="Becco di tucano"/> TucaTV<span class="beta">BETA</span></a><div class="navlabel">IL TUO SPAZIO TV</div><button aria-label="Catalogo" class:chosen={page==='channels'} onclick={()=>nav('channels')}>▦ <span>Catalogo</span></button><button aria-label="Le mie playlist" class:chosen={page==='playlists'} onclick={()=>nav('playlists')}>▤ <span>Le mie playlist</span></button><button aria-label="Preferiti" onclick={()=>{nav('channels');group='Preferiti'}}>♡ <span>Preferiti</span><small>{favorites.length}</small></button>{#if currentPlayback}<div class="current-playback"><button class="resume-player" onclick={returnToPlayer} aria-label={'Torna al player: '+currentPlayback.title}>▶ <span>Torna al player<small>{currentPlayback.title}</small></span></button><button class="stop-current" onclick={stopCurrent} aria-label="Interrompi riproduzione">■ <span>Interrompi</span></button></div>{/if}<div class="asidebottom"><span class="dot"></span> Tutto sul tuo dispositivo<p>Nessun account. Solo la tua TV.</p><small>TucaTV / VERSIONE 0.9.1</small></div></aside>
<main><header><span>{page==='playlists'?'LIBRERIA':page==='player'?'IN RIPRODUZIONE':'IL TUO CATALOGO'}</span><div><span class="dot"></span> {isDesktop?'Desktop · VLC':isAndroid?'Android · VLC':'Browser'} <span class="clock">{time(clock)}</span></div></header>
{#if loading}<section class="import-progress" class:complete={loading.phase==='done'} class:background-refresh={startupRefreshing} aria-label="Avanzamento caricamento playlist" aria-busy={busy}><div class="import-progress-top"><strong role="status">{loading.title}</strong>{#if loading.percent!==null}<b>{loading.percent}%</b>{/if}{#if !busy}<button aria-label="Chiudi avanzamento" onclick={()=>loading=null}>×</button>{/if}</div>{#if loading.phase!=='error'}<progress class:indeterminate={loading.percent===null} max="100" value={loading.percent??undefined} aria-label={loading.title}></progress>{/if}<p>{refreshLabel?refreshLabel+' · ':''}{loading.detail}</p><small>{loading.phase==='download'?'1 / 3 · Trasferimento':loading.phase==='parse'?'2 / 3 · Lettura':loading.phase==='save'?'3 / 3 · Salvataggio':loading.phase==='done'?'Completato':''}</small></section>{/if}
{#if failedSource&&!isNative}<div class="notice"><p>Puoi scaricare la playlist separatamente e importare il file. Questo risolve l’importazione, ma non cambia la compatibilità degli stream nel browser.</p><a href={safe(failedSource)} target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer">Apri link playlist ↗</a></div>{/if}
{#if message}<div class="notice" role="status">{message}<button onclick={()=>message=''} aria-label="Chiudi messaggio">×</button></div>{/if}
{#if !storageReady}<div class="empty">Caricamento della raccolta…</div>{:else if page==='playlists'}
{#if categoryEditor}{#each lists.filter(p=>p.id===categoryEditor) as p (p.id)}<CategoryManager playlist={p} onsave={saveCategories} onclose={()=>{categoryEditor=null;tick().then(ensureFocus);}}/>{/each}{:else}
<div class="heading"><div><p class="eyebrow">LA TV, A MODO TUO</p><h1>Le mie playlist<span>.</span></h1><p>Un posto per tutti i tuoi canali. Il resto rimane fuori.</p></div><span class="counter">{lists.length} playlist</span></div>
<div class="importgrid"><section class="panel"><div class="sectiontitle"><span class="iconbox">＋</span><div><h2>Aggiungi una playlist</h2><p>Collega una sorgente e inizia a guardare.</p></div></div><label>Nome della playlist<input bind:value={name} placeholder="Es. TV di casa"/></label><label>Link M3U<input bind:value={url} type="url" placeholder="https://esempio.it/playlist.m3u"/></label><label>Guida TV · opzionale<input bind:value={epgUrl} type="url" placeholder="URL della guida XMLTV"/></label><button class="primary full" disabled={busy||!url} onclick={()=>add() }>{busy?'Caricamento…':'Aggiungi playlist'} <span>↗</span></button><div class="divider">oppure</div><label class="upload">↥ <b>Carica un file M3U</b><span>Scegli un file dal dispositivo</span><input type="file" accept=".m3u,.m3u8" disabled={busy} onchange={e=>{if(e.target.files[0])add(e.target.files[0]);e.target.value=''}}/></label></section><section class="intro"><div class="orbit"><img src="/tucatv-mark.svg" alt=""/></div><p class="eyebrow">MENO DISTRAZIONI. PIÙ TV.</p><h2>Premi play.<br/>Sentiti a casa.</h2><p>Le tue playlist, i tuoi preferiti e una guida essenziale. Tutto in un’interfaccia che lascia spazio a ciò che guardi.</p><button class="textbutton" disabled={busy} onclick={demo}>Esplora con una playlist demo ↗</button><small>Due video di esempio · nessun canale incluso</small></section></div>
<div class="sectionrow"><h2>La tua raccolta</h2><span>Salvata sul dispositivo</span></div>{#if !lists.length}<div class="empty compact">Aggiungi la prima playlist.<button onclick={demo} disabled={busy}>Esplora la demo</button></div>{/if}<div class="collection">{#each lists as p}<article class="playlistcard"><span class="iconbox">▤</span><h3>{p.name}</h3><p>{p.channels.length} canali · {p.source?'Sorgente online':'File locale'}</p><small>Aggiornata {new Date(p.updated).toLocaleDateString('it')}</small><div class="actions"><button class="primary" onclick={()=>{active=p.id;group='Tutti';page='channels';loadEpg()}}>Apri →</button>{#if p.source}<button disabled={busy} onclick={()=>refresh(p)}>Aggiorna</button>{/if}<button disabled={busy} onclick={()=>editCategories(p)}>Categorie{p.hiddenGroups?.length?' · '+p.hiddenGroups.length+' nascoste':''}</button><button disabled={busy} onclick={()=>remove(p.id)} aria-label={'Elimina '+p.name}>Elimina</button></div></article>{/each}</div>
{/if}
{:else if page==='channels'}
<div class="heading"><div><p class="eyebrow">SCEGLI COSA GUARDARE</p><h1>{catalogMode==='live'?'Live TV':'On demand'}<span>.</span></h1><p>{catalogMode==='live'?'Il mondo, in diretta.':'Scegli una storia. Premi play.'}</p></div><select bind:value={active} onchange={()=>{group='Tutti';loadEpg()}} aria-label="Playlist">{#each lists as p}<option value={p.id}>{p.name}</option>{/each}</select></div>
{#if playlist?.channels.length}<div class="catalog-tabs"><button class:active={catalogMode==='live'} aria-pressed={catalogMode==='live'} onclick={()=>{catalogMode='live';group='Tutti'}}>● Live TV</button><button class:active={catalogMode==='vod'} aria-pressed={catalogMode==='vod'} onclick={()=>{catalogMode='vod';group='Tutti'}}>▶ Film e serie</button><div class="top-spacer"></div><button class:active={view==='catalog'} onclick={()=>view='catalog'} aria-label="Vista catalogo">▦</button><button class:active={view==='list'} onclick={()=>view='list'} aria-label="Vista griglia">☷</button></div>{#if epgMessage}<div class="notice" role="status">{epgMessage}</div>{/if}<div class="toolbar"><input class="search" bind:value={query} placeholder="Cerca nel catalogo…" aria-label="Cerca nel catalogo"/><label class="epgbutton">↥ Importa EPG<input type="file" accept=".xml" onchange={e=>{if(e.target.files[0])loadEpg(e.target.files[0]);e.target.value=''}}/></label></div><div class="catalog-filters"><label>Categoria<select bind:value={group}>{#each groups as g}<option value={g}>{g}</option>{/each}</select></label><span>{filtered.length.toLocaleString('it')} titoli</span></div>{#if view==='catalog'&&group==='Tutti'&&!query}<Catalog items={filtered} lastChannel={lastChannel} mode={catalogMode} {play} {favorite} {favorites} {now} oncategory={g=>{group=g;view='list'}}/>{:else}<TVCatalog items={filtered} {play} {favorite} {favorites} {now}/>{/if}{:else}<div class="empty"><h2>Il tuo schermo ti aspetta.</h2><p>Aggiungi una playlist per trovare qui tutti i tuoi canali.</p><button class="primary" onclick={()=>nav('playlists')}>Aggiungi playlist ↗</button></div>{/if}
{:else}
<div class="watch-heading"><button class="textbutton" onclick={()=>nav('channels')}>← La tua TV</button><span>TUCA PLAYER</span></div>
<Player error={playbackError} onexternal={exportSelected} {video} channel={selected} programme={now(selected)} favorite={favorites.includes(selected.url)} mode={playbackMode} onback={()=>nav('channels')} onprevious={()=>changeChannel(-1)} onnext={()=>changeChannel(1)} onretry={()=>play(selected)} onfavorite={()=>favorite(selected)} onmode={m=>{playbackMode=m;play(selected)}}>
<video bind:this={video} autoplay playsinline onloadeddata={()=>clearTimeout(playbackTimer)} onerror={mediaError}><track kind="captions"/></video>
</Player><div class="watch-info"><div><p class="eyebrow">{kind(selected)==='vod'?'ON DEMAND':'A SEGUIRE'}</p><h2>{kind(selected)==='vod'?selected.name:next(selected)?.title||'Il prossimo programma, quando disponibile.'}</h2><p>{kind(selected)==='vod'?'On demand · '+selected.group:next(selected)?time(next(selected).start):'Collega una guida XMLTV alla tua playlist.'}</p></div><div class="keyboard-hint">Spazio · Play / pausa<br/>F · Schermo intero</div></div>

{/if}<footer>TucaTV <span>La tua TV. Il tuo ritmo.</span><span>Playlist e preferiti restano su questo dispositivo.</span></footer></main></div>
